def solve_search(m_max, n_max, p_list):
    solutions = []
    for m in range(1, m_max + 1):
        for n in range(1, n_max + 1):
            for p in p_list:
                # Condition 1: m^2 + n = p^a, a >= 2
                S1 = m**2 + n
                is_s1_power = False
                a = 1
                while p**a <= S1:
                    if p**a == S1:
                        if a >= 2:
                            is_s1_power = True
                        break
                    a += 1

                if not is_s1_power:
                    continue

                # Condition 2: m + n^2 = p^b, b >= 2
                S2 = m + n**2
                is_s2_power = False
                b = 1
                while p**b <= S2:
                    if p**b == S2:
                        if b >= 2:
                            is_s2_power = True
                        break
                    b += 1

                if is_s1_power and is_s2_power:
                    solutions.append((m, n, p))
    return solutions

m_max = 10
n_max = 10
p_list = [2, 3, 5]

solutions = solve_search(m_max, n_max, p_list)
print("Found solutions (m, n, p):")
for sol in solutions:
    print(sol)

# Specific focus on p=5
solutions_p5 = [sol for sol in solutions if sol[2] == 5]
print("\nSolutions specifically for p=5 (m, n, p):")
for sol in solutions_p5:
    print(sol)
